document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll("form[data-single-submit]").forEach(t=>{t.addEventListener("submit",e=>{if("true"===t.dataset.submitting)return void e.preventDefault();t.dataset.submitting="true";const i=e.submitter;i&&window.setTimeout(()=>{i.disabled=!0,i.setAttribute("aria-disabled","true")},0)})})});
